// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address user) public {
        vm.assume(user != address(0));
        vm.assume(depositAmount > 0 && depositAmount <= 1e36);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= depositAmount);
        vm.assume(user != address(this));

        vm.deal(user, depositAmount);
        vm.prank(user);
        c.addToBalance{value: depositAmount}();

        uint256 balanceBefore = c.getBalance(user);

        uint256 beforeContractBalance = address(c).balance;
        vm.prank(user);
        bool ok = true;
        try c.withdrawBalance() { ok = true; } catch { ok = false; }

        uint256 balanceAfter = c.getBalance(user);
        uint256 expectedBalance = 0;
        if (ok) {
            expectedBalance = 0;
        } else {
            expectedBalance = balanceBefore;
        }

        assertTrue(balanceAfter == expectedBalance);
    }
}
